"use client";
/* Alien, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Alien(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("alien"); }, []);
  return React.createElement("piix-sprite", { "name": "alien", ...piixAttrs(props) });
}

export default Alien;
